const rows = new Map<string, Row>(delegationLocaleRows.map(row => [row[0], row]))
export function delegationLocaleText(language: ClientLanguage, source: string, ...values: (string | number)[]) {
  const customStop = /^(-?\d+(?:\.\d+)?)%까지$/.exec(source)
  if (customStop && !rows.has(source)) return delegationLocaleText(language, '{0}%까지', customStop[1])
  const singular = singularRows.get(source)
  const row = language !== 'ko' && singular && new Intl.PluralRules(language).select(Number(values[singular.slot])) === 'one' ? singular.row : rows.get(source)
  const text = row?.[languages.indexOf(language)] ?? connectionLocaleText(language, source)
  return text.replace(/\{(\d+)\}/g, (slot, index: string) => values[Number(index)] === undefined ? slot : String(values[Number(index)]))
}
export function useDelegationLocaleText() {
  const { language } = useClientPreferences()
  return (source: string, ...values: (string | number)[]) => delegationLocaleText(language, source, ...values)
}
